CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,username TEXT UNIQUE COLLATE NOCASE,pw TEXT,gsub TEXT UNIQUE,created INTEGER NOT NULL,pub TEXT NOT NULL DEFAULT '{}',shared TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS sessions(h TEXT PRIMARY KEY,uid INTEGER NOT NULL,exp INTEGER NOT NULL,csrf TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sess_uid ON sessions(uid);
CREATE TABLE IF NOT EXISTS friends(a INTEGER NOT NULL,b INTEGER NOT NULL,status TEXT NOT NULL,PRIMARY KEY(a,b));
CREATE INDEX IF NOT EXISTS fr_b ON friends(b);
CREATE TABLE IF NOT EXISTS saves(uid INTEGER NOT NULL,pack TEXT NOT NULL,data TEXT NOT NULL,xp INTEGER NOT NULL,upd INTEGER NOT NULL,PRIMARY KEY(uid,pack));
CREATE TABLE IF NOT EXISTS weekly(uid INTEGER NOT NULL,wk TEXT NOT NULL,xp INTEGER NOT NULL,PRIMARY KEY(uid,wk));
CREATE TABLE IF NOT EXISTS rl(k TEXT PRIMARY KEY,w INTEGER NOT NULL,n INTEGER NOT NULL);
